body.onloadscript:

	$sObject._vp[0].parentElement.classList.add("sepoa_form_label_top");

    builder = $sObject.builder = new SepoaScreenBuilder(builderBox);
    builder.drawEditor();

    if(Sepoa.request.page && Sepoa.request.__SID__){
    	var info = {};

    	var page = Sepoa.request.page;
    	if(page.indexOf('/') == 0){
    		page = page.substring(1);
    	}
    	if(page.indexOf('sux') == page.length - 3){
    		page = page.substring(0, page.length - 3)+"xml";
    	}
    	var sPage = page.split('/');

    	if(sPage.length == 3 && (sPage[2].indexOf(sPage[0] + sPage[1]) == 0)){
    		info = {
    			NONSTD_PATH:"",
    			PATH:"/"+page,
    			PATH_1:sPage[0],
    			PATH_2:sPage[1],
    			PATH_3:sPage[0]+sPage[1],
    			NAME:sPage[2].substring((sPage[0]+sPage[1]).length,sPage[2].length-4),
    			PROJECT:"FRWK"
    		}
    	}else{
    		//미작성
    	}

    	var sid = Sepoa.request.__SID__;

    	info.PREFIX = sid.substring(0, sid.indexOf("_"));
    	info.CODE = sid.substring(sid.indexOf("_") + 1);

    	//builder.initProject([{info:info}]);
    	builder.popupAction("MENU_NEW",info);
    }else if(Sepoa.request.page){
    	builder.load(Sepoa.request.page);
    }
